// Validators must fail loudly instead of skipping: missing sync targets,
// orphaned generated files, stale allowlist entries, unpinned third-party
// components, and stack rules hidden behind an example marker.
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { validateClaudeSkills } from '../scripts/sync-claude-skills.mjs';
import { validateDelegateRuntimeAdapters } from '../scripts/sync-delegate-runtime-adapters.mjs';
import { prefilterTargets, validateLevelPrefilter } from '../scripts/sync-level-prefilter.mjs';
import { validateLegalReadiness } from '../scripts/validate-legal-readiness.mjs';
import { validateNeutralPaths } from '../scripts/validate-neutral-paths.mjs';
import { validateStackNeutrality } from '../scripts/validate-stack-neutrality.mjs';
import { makeTempRepo } from './helpers.mjs';

const sourceRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

async function fixtureWith(entries) {
  const root = await makeTempRepo('workflow-kit-guards-');
  for (const entry of entries) {
    await fs.cp(path.join(sourceRoot, entry), path.join(root, entry), { recursive: true });
  }
  return root;
}

test('level pre-filter check fails when a target adapter is missing', async () => {
  const root = await fixtureWith(['.agents/instructions.md', ...prefilterTargets]);
  await fs.rm(path.join(root, 'ANTIGRAVITY.md'));

  const result = await validateLevelPrefilter({ root });

  assert.equal(result.ok, false);
  assert.ok(result.failures.some((failure) => failure.includes('Level pre-filter target missing: ANTIGRAVITY.md')), result.failures.join('\n'));
});

test('Claude skill check flags orphaned generated wrappers', async () => {
  const root = await fixtureWith(['.agents/skills/registry.json', '.claude/skills', 'templates/runtime-adapters/claude/.claude/skills']);
  const marker = '<!-- Generated by scripts/sync-claude-skills.mjs. Do not edit. -->';
  await fs.mkdir(path.join(root, '.claude/skills/retired-skill'), { recursive: true });
  await fs.writeFile(path.join(root, '.claude/skills/retired-skill/SKILL.md'), `${marker}\n`, 'utf8');
  await fs.mkdir(path.join(root, '.claude/skills/my-own-skill'), { recursive: true });
  await fs.writeFile(path.join(root, '.claude/skills/my-own-skill/SKILL.md'), '# Hand-written\n', 'utf8');
  await fs.mkdir(path.join(root, 'templates/runtime-adapters/claude/.claude/skills/stale'), { recursive: true });
  await fs.writeFile(path.join(root, 'templates/runtime-adapters/claude/.claude/skills/stale/SKILL.md'), '# Stale\n', 'utf8');

  const result = await validateClaudeSkills({ root });

  assert.ok(result.failures.includes('Orphaned generated Claude skill: .claude/skills/retired-skill/SKILL.md'), result.failures.join('\n'));
  assert.ok(result.failures.includes('Orphaned generated Claude skill: templates/runtime-adapters/claude/.claude/skills/stale/SKILL.md'), result.failures.join('\n'));
  assert.equal(result.failures.some((failure) => failure.includes('my-own-skill')), false);
});

test('delegate adapter check flags orphaned generated adapters', async () => {
  const root = await fixtureWith([
    'scripts/delegate-agent-catalog.json',
    'scripts/copilot-model-routing.mjs',
    'scripts/verify-copilot-model-evidence.mjs',
    'templates/repo-overlay-fhh-ia-ecosystem-full/.agents/delegation/delegate-contract.md'
  ]);
  await fs.mkdir(path.join(root, '.codex/agents'), { recursive: true });
  await fs.writeFile(path.join(root, '.codex/agents/retired.toml'), '# Generated by scripts/sync-delegate-runtime-adapters.mjs. Do not edit.\n', 'utf8');
  await fs.mkdir(path.join(root, '.claude/agents'), { recursive: true });
  await fs.writeFile(path.join(root, '.claude/agents/my-own-agent.md'), '# Hand-written\n', 'utf8');
  await fs.mkdir(path.join(root, 'templates/runtime-adapters/copilot/.github/agents'), { recursive: true });
  await fs.writeFile(path.join(root, 'templates/runtime-adapters/copilot/.github/agents/retired.agent.md'), '# Stale\n', 'utf8');

  const result = await validateDelegateRuntimeAdapters({ root });

  assert.ok(result.failures.includes('Orphaned generated delegate adapter: .codex/agents/retired.toml'), result.failures.join('\n'));
  assert.ok(result.failures.includes('Orphaned generated delegate adapter: templates/runtime-adapters/copilot/.github/agents/retired.agent.md'), result.failures.join('\n'));
  assert.equal(result.failures.some((failure) => failure.includes('my-own-agent')), false);
});

test('neutral path check flags allowlist entries for files that no longer exist', async () => {
  const root = await fixtureWith(['.agents/skills', '.agents/delegation']);
  await fs.rm(path.join(root, '.agents/skills/06-patterns/authoring/init-legacy-attachments/SKILL.md'));

  const result = await validateNeutralPaths({ root });

  assert.ok(result.failures.includes('Runtime path allowlist entry for a file that no longer exists: .agents/skills/06-patterns/authoring/init-legacy-attachments/SKILL.md'), result.failures.join('\n'));
});

test('stack neutrality accepts a stack only after the example marker', async () => {
  const root = await fixtureWith(['.agents/skills', '.agents/delegation', 'scripts/stack-rule-inventory.json', 'templates/stack-packs']);
  const skill = path.join(root, '.agents/skills/02-implement/implement-change/SKILL.md');
  await fs.appendFile(skill, '\nWrite every spec with RSpec (e.g. unit specs).\nRun the focused suite (for example RSpec or Vitest).\n', 'utf8');

  const result = await validateStackNeutrality({ root });
  const skillFailures = result.failures.filter((failure) => failure.startsWith('.agents/skills/02-implement/implement-change/SKILL.md'));

  assert.equal(skillFailures.length, 1, result.failures.join('\n'));
  assert.ok(skillFailures[0].includes('"RSpec"'));
});

test('legal check validates every provenance component, not only the pinned ones', async () => {
  const root = await fixtureWith(['THIRD_PARTY_NOTICES.md', 'docs/legal', 'templates/repo-overlay-fhh-ia-ecosystem-full']);
  const manifestPath = path.join(root, 'docs/legal/third-party/provenance.json');
  const manifest = JSON.parse(await fs.readFile(manifestPath, 'utf8'));
  manifest.components.push({
    name: 'new-library',
    status: 'VERIFIED',
    license: 'MIT',
    upstream: { repository: 'https://github.com/example/new-library', commit: 'main' },
    localPaths: ['templates/missing-vendored-file.js'],
    licenseFile: 'docs/legal/third-party/licenses/MIT-new-library.txt'
  });
  await fs.writeFile(manifestPath, JSON.stringify(manifest, null, 2), 'utf8');

  const { failures } = validateLegalReadiness({ root });

  for (const expected of [
    'Third-party provenance manifest must pin an upstream repository and full commit for new-library.',
    'THIRD_PARTY_NOTICES.md must attribute new-library (example/new-library).',
    'Third-party provenance manifest has no readable license file for new-library.',
    'Third-party provenance manifest references missing local path: templates/missing-vendored-file.js'
  ]) {
    assert.ok(failures.includes(expected), `${expected}\n---\n${failures.join('\n')}`);
  }
});
